        if (depth + 1 + estimate < cost) {
          best = firstMove;
          cost = depth + 1 + estimate;
        }
      } else if (queue.length < 128) {
        queue.push({position: next, depth: depth + 1, first: firstMove});
      }
    }
  }
  return best;
}

