        const moves = seat === turn ? legal.filter(move => move.tile === tile) : [];
        const position = ecPosition(tile, at);
        const id = tileId(seat, tile);
        const piece = {id, board, position, type: tile === 0 ? 'core' : tile < 3 ? 'wide' : tile < 6 ? 'tall' : 'chip',
